		MustDo: []string{'''
assert old in s
s = s.replace(old, new, 1)

# 3. validation notes: clean checkout + cannot-verify
old = '''			"Re-running the pivot command is what proves the constraint is satisfied: the invalidated count must reach zero.",'''
new = '''			"Re-running the pivot command is what proves the constraint is satisfied: the invalidated count must reach zero.",
